class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False
        self.count = 0  # Kaç kelime bu düğümden geçiyor

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
            node.count += 1
        node.is_end = True

    def search(self, word):
        node = self._find_node(word)
        return node is not None and node.is_end

    def starts_with(self, prefix):
        return self._find_node(prefix) is not None

    def autocomplete(self, prefix, limit=10):
        node = self._find_node(prefix)
        if not node:
            return []
        results = []
        self._dfs(node, prefix, results, limit)
        return results

    def _find_node(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return None
            node = node.children[char]
        return node

    def _dfs(self, node, path, results, limit):
        if len(results) >= limit:
            return
        if node.is_end:
            results.append(path)
        for char, child in sorted(node.children.items()):
            self._dfs(child, path + char, results, limit)

# Kullanım
trie = Trie()
for word in ['python', 'pytorch', 'pandas', 'pip']:
    trie.insert(word)
print(trie.autocomplete('py'))  # ['python', 'pytorch']
