from typing import TypeVar, Generic, Protocol, Optional, Callable

# Temel type hints
def greet(name: str, age: int) -> str:
    return f"{name} ({age})"

# Container types (Python 3.9+)
def process(items: list[int]) -> dict[str, int]:
    return {"sum": sum(items), "count": len(items)}

# Optional ve Union (Python 3.10+)
def find(items: list[str], query: str) -> str | None:
    return next((x for x in items if query in x), None)

# TypeVar (Generics)
T = TypeVar('T')

def first(items: list[T]) -> T | None:
    return items[0] if items else None

# Generic Class
class Stack(Generic[T]):
    def __init__(self) -> None:
        self._items: list[T] = []

    def push(self, item: T) -> None:
        self._items.append(item)

    def pop(self) -> T:
        return self._items.pop()

stack: Stack[int] = Stack()
stack.push(42)

# Protocol (Structural Subtyping)
class Printable(Protocol):
    def __str__(self) -> str: ...

def display(obj: Printable) -> None:
    print(str(obj))

# Callable
def apply(func: Callable[[int], int], value: int) -> int:
    return func(value)
